function initializeShared() {
    ej.base.L10n.load({
        "en-EN": {
            grid: {
                EmptyRecord: "There are no trees in this project"
            },
            pager: {
                totalItemsInfo: "({0} trees)",
                pagerDropDown: "trees per page",
                pagerAllDropDown: "trees"
            }
        }
    });
    var a = $("<ul class='projectList'></ul>");
    shared_projects.forEach(function (b) {
        var e = "project-" + b.id
            , c = $("<li>", {
                id: e,
                "class": "project"
            });
        c.append("<div class='project_title d-flex flex-row'><div style='padding-right: 5px'></div><div class='flex-grow-1 p_title_js'>" + b.t + "</div></div>");
        var g = $("<div>", {
            "class": "project_content"
        });
        0 < b.c && g.css("display", "none");
        g.append("<p class='project_description p-2' data-underline='false' data-pk='" + b.id + "'>" + b.d + "</p>");
        b = $("<table>", {
            id: e + "-data",
            "data-pid": b.id,
            "class": "tTable"
        });
        g.append(b);
        c.append(g);
        a.append(c)
    });
    $("#shared_data").append(a);
    for (var c = 0; c < shared_projects.length; c++) {
        var b = shared_projects[c];
        (new ej.grids.Grid({
            pIdx: c,
            dataSource: b.data,
            locale: "en-EN",
            allowSelection: !1,
            allowSorting: !0,
            allowReordering: !0,
            enableHover: !1,
            allowPaging: !0,
            allowFiltering: !0,
            filterSettings: {
                type: "Menu"
            },
            toolbar: ["Search"],
            created: function () {
                $("#project-" + this.projectId + "-data_searchbutton").parent().append("<span style='min-width: 32px' data-pid='" + this.projectId + "' onclick='clearProjectSearch(this)' id=\"project-" + this.projectId + '-data_searchclrbutton" class="e-input-group-icon e-cancel-icon e-icons" tabindex="-1" title="Clear" aria-label="clear"></span>')
            },
            queryCellInfo: function (a) {
                "ds" === a.column.field ? ($(a.cell).find(".dsClip").each(function () {
                    var a = $(this).attr("data-dsc");
                    tippy(this, {
                        placement: "top",
                        theme: "light-border",
                        allowHTML: !0,
                        content: "Show all " + a + " datasets"
                    })
                }),
                    $(a.cell).find(".dsBox").each(function () {
                        var a = "<table><tr><th>Label:</th><td>" + $(this).attr("data-lb") + "</td></tr><tr><th>Type:</th><td>" + $(this).attr("data-t") + "</td></tr></table>";
                        $(this).attr("data-lb") && tippy(this, {
                            placement: "top",
                            theme: "light-border",
                            allowHTML: !0,
                            content: a
                        })
                    })) : "f" === a.column.field ? $(a.cell).find("img").each(function () {
                        tippy(this, {
                            placement: "top",
                            theme: "light-border",
                            allowHTML: !0,
                            content: $(this).attr("data-tip")
                        })
                    }) : "cp" === a.column.field && $(a.cell).find("button").each(function () {
                        tippy(this, {
                            placement: "top",
                            theme: "light-border",
                            allowHTML: !0,
                            content: $(this).attr("data-tip")
                        })
                    })
            },
            pageSettings: {
                pageSize: 10,
                pageSizes: [5, 10, 20, 50, 100, "All"]
            },
            showColumnMenu: !0,
            columns: [{
                field: "id",
                visible: !1,
                isPrimaryKey: !0,
                showInColumnChooser: !1
            }, {
                field: "dsEx",
                visible: !1,
                showInColumnChooser: !1
            }, {
                field: "dsSr",
                visible: !1,
                showInColumnChooser: !1
            }, {
                field: "t",
                headerText: "Tree",
                textAlign: "Right",
                showInColumnChooser: !1,
                type: "string",
                maxWidth: 300,
                clipMode: "EllipsisWithTooltip",
                autoFit: !0,
                template: "<a class='tLink' href='/tree/${id}'>${t}</a>"
            }, {
                field: "d",
                headerText: "Description",
                type: "string",
                clipMode: "EllipsisWithTooltip",
                maxWidth: 300,
                autoFit: !0,
                template: "${if(d)} ${d} ${else} <span class='text-muted small'>no description</span> ${/if}"
            }, {
                field: "s",
                headerText: "Leaves",
                type: "number",
                textAlign: "Right",
                autoFit: !0
            }, {
                field: "ds",
                headerText: "Datasets",
                template: "#dsTemplate",
                autoFit: !0,
                clipMode: "Ellipsis",
                allowFiltering: !1
            }, {
                field: "v",
                headerText: "Views",
                textAlign: "Center",
                template: "#vTemplate",
                autoFit: !0,
                allowFiltering: !1
            }, {
                field: "f",
                headerText: "Features",
                template: "#featTemplate",
                autoFit: !0,
                clipMode: "Ellipsis",
                allowFiltering: !1,
                allowSorting: !1
            }, {
                field: "i",
                headerText: "Inserted",
                type: "date",
                format: "yyyy-MM-dd",
                autoFit: !0
            }, {
                field: "u",
                headerText: "Updated",
                type: "datetime",
                format: "yyyy-MM-dd HH:mm",
                autoFit: !0
            }, {
                field: "cp",
                headerText: "",
                showInColumnChooser: !1,
                allowReordering: !1,
                clipMode: "Clip",
                type: "string",
                width: 50,
                template: "<button style='line-height: 1' data-tip='Copy this tree into your iTOL account' class='btn btn-sm' data-id='${id}' onclick='copyTreePop(this)'><i class='fad fa-copy'></i></button>"
            }]
        })).appendTo("#project-" + b.id + "-data")
    }
}
function popViewListShared(a) {
    isPanelOpen("treeViewListPop") && closePanel("treeViewListPop");
    for (var c = $(a).attr("data-tid"), b = $(a).closest(".tTable")[0].ej2_instances[0].pIdx, d = [], e = 0; e < shared_projects[b].data.length; e++)
        shared_projects[b].data[e].id == c && (d = shared_projects[b].data[e].v);
    if (d[0]) {
        b = '<div style="min-width:400px; max-width: 600px" class="p-0"><table class="acViewPop"><tr><th>View name</th><th>Description</th></tr>';
        for (e = 0; e < d.length; e++) {
            var f = d[e].t;
            f || (f = '<span class="text-muted small">no description</span>');
            b += "<tr><td><a href='/tree/" + c + "/" + d[e].id + "'>" + d[e].n + "</a></td><td>" + f + "</td></tr>"
        }
        jsPanel.modal.create({
            content: b + "</table></div>",
            id: "treeViewListPop",
            header: !1,
            headerTitle: "Restore a tree view",
            headerControls: {
                minimize: "remove",
                maximize: "remove",
                smallify: "remove"
            },
            footerToolbar: ['<span class="text-muted small"><i class="far fa-info-circle"></i> Click on a name to display the tree and restore the view.</span>'],
            theme: "bootstrap-primary",
            contentSize: "800 100",
            panelSize: {
                width: "auto",
                height: "auto"
            },
            position: {
                my: "right-top",
                at: "right-bottom",
                of: $(a)
            },
            callback: function (b) {
                $("#jsPanel-modal-backdrop-treeViewListPop").css("background", "none");
                b.resize("auto", "auto").reposition({
                    my: "right-top",
                    at: "right-bottom",
                    of: $(a)
                })
            }
        })
    }
}
function copyTreePop(a) {
    var c = $(a).attr("data-id");
    a = "<div class='p-2' style='max-width: 500px'><p class='alert alert-info m-0'>You can copy the tree <b>'" + $(a).closest("tr").find(".tLink").text() + "'</b> into a project &rsquo;<b>Imported trees</b>&rsquo; in your own iTOL account. The project will be automatically created if it does not exist.</p></div>";
    jsPanel.modal.create({
        content: a,
        headerTitle: "Copy tree to your account?",
        headerLogo: "<i class='fad fa-copy ml-2'></i>",
        headerControls: "closeonly",
        theme: "bootstrap-primary",
        contentSize: {
            width: "auto",
            height: "auto"
        },
        footerToolbar: ['<button id="tCpBut" class="btn btn-sm btn-primary mr-1"><i class="fad fa-copy"></i> Copy tree</button>', '<button id="tCpClose" class="btn btn-sm btn-secondary" >Cancel</button>'],
        callback: function (a) {
            $("#tCpBut").on("click", function () {
                var d = {};
                d.id = c;
                $.ajax({
                    url: "/ajax/personal/copySharedTree.cgi",
                    type: "post",
                    data: d,
                    success: function () {
                        infoBox("Tree copied successfully.")
                    },
                    error: ajaxError
                });
                a.close()
            });
            $("#tCpClose").on("click", function () {
                a.close()
            })
        }
    })
}
