function popLogin() {
    isPanelOpen("loginPop") ? closePanel("loginPop") : jsPanel.create({
        content: "<div class='p-2'><form><div class='form-group row'><label class='col-sm-4 col-form-label text-right pr-0' for='loginFrmIn'>Login</label><div class='col-sm-8'><input type='text' class='form-control form-control-sm' id='loginFrmIn' value=''></div></div><div class='form-group row'><label class='col-sm-4 col-form-label text-right pr-0' for='pwdFrmIn'>Password</label><div class='col-sm-8'><input type='password' class='form-control form-control-sm' id='pwdFrmIn' value=''></div></div><div class='form-group row'><label class='col-sm-4 col-form-label'></label><div class='col-sm-8'><div class='form-check'><input class='form-check-input' type='checkbox' value='1' id='rememberLogin'><label class='form-check-label' for='rememberLogin'>Keep me signed in</label></div></div></div></form><div style='text-align:right'>External sign in via: <a class='btn btn-sm btn-outline-primary' href='login.cgi?ext=1'><img class='img-responsive mr-2' height='20px' src='/img/micro_signin.png' /> <img class='img-responsive mr-2' height='20px' src='/img/google_signin.png' /></a></div></div>",
        id: "loginPop",
        headerTitle: "Sign in to your iTOL account",
        headerLogo: "<i class='fad fa-sign-in-alt ml-2'></i>",
        theme: "bootstrap-primary",
        contentSize: {
            width: "auto",
            height: "auto"
        },
        position: {
            my: "right-top",
            at: "right-bottom",
            of: "#loginHeadBut"
        },
        headerControls: {
            minimize: "remove",
            maximize: "remove"
        },
        footerToolbar: ['<a style="flex: 1 1 auto" class="small" href="/lost_password.cgi" ><i class="far fa-key"></i> Forgot password?</a>', '<button id="cPanelBut" class="btn btn-primary btn-sm mr-1 px-3">Sign in</button>', '<button id="cPanelClose" class="btn btn-secondary btn-sm" >Cancel</button>'],
        callback: function (a) {
            $("#loginFrmIn").focus();
            $("#cPanelBut").on("click", function () {
                if (0 == $("#loginFrmIn").val().length)
                    error("Login cannot be empty."),
                        $("#loginFrmIn").focus();
                else if (0 == $("#pwdFrmIn").val().length)
                    error("Password cannot be empty."),
                        $("#pwdFrmIn").focus();
                else {
                    var c = {};
                    c.l = $("#loginFrmIn").val();
                    c.p = $("#pwdFrmIn").val();
                    $("#rememberLogin").is(":checked") && (c.r = 1);
                    $.ajax({
                        url: "/ajax/personal/popLogin.cgi",
                        type: "post",
                        data: c,
                        success: function (a) {
                            $("#uploadHead").html("<a class='nav-link' href='/personal_page.cgi'><i class='fad fa-user'></i> <span class='navTxt'>My Trees</span></a>");
                            $("#hdrUname").text(a);
                            $(".uboxShow").show();
                            $(".uboxHide").hide()
                        },
                        error: ajaxError
                    });
                    a.close()
                }
            });
            $("#cPanelClose").on("click", function () {
                a.close()
            })
        }
    })
}
function isVarEmpty(a) {
    return null == a || "undefined" == typeof a || "number" == typeof a && isNaN(a) ? !0 : !1
}
function updateTooltips(a, c) {
    0 != user_settings.helpHints && (c || (c = "top"),
        $(a).each(function () {
            $(this).attr("data-tip") && tippy(this, {
                placement: c,
                theme: "light-border",
                allowHTML: !0,
                content: $(this).attr("data-tip")
            })
        }))
}
function updateTooltipsEllipsis(a) {
    0 != user_settings.helpHints && $(a).each(function () {
        $(this).html().length && $(this)[0].offsetWidth != $(this)[0].scrollWidth && tippy(this, {
            theme: "light-border",
            content: $(this).html()
        })
    })
}
function updateControlTooltips() {
    0 != user_settings.helpHints && ($("#controlBox tr[data-tip],#controlBox div[data-tip]").each(function () {
        tippy(this, {
            placement: "left",
            theme: "light-border",
            allowHTML: !0,
            content: $(this).attr("data-tip")
        })
    }),
        $("#controlBox label[data-tip], #controls button[data-tip], #controlBox input[data-tip]").each(function () {
            tippy(this, {
                theme: "light-border",
                allowHTML: !0,
                content: $(this).attr("data-tip")
            })
        }))
}
function closeDropModal() {
    $("body").removeClass("fileover")
}
